"""Traffic capture manager"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
# import os
from builtins import object
from ute_common_store.store import Store     # user ute_store
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.traffic.capture.tool_factory import ToolFactory
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from future import standard_library
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
standard_library.install_aliases()
logger = BackgroundLogger.Instance()
# from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable


class TrafficCaptureManager(object):
    """Traffic capture manager"""
    store = Store()

    def __init__(self):
        self.config = ConfigHandler.get_config()
        self.capture_factory = None

    @check_rat
    def traffic_capture_start(self, **kwargs):
        """Start traffic capture"""
        # Move capture filter to kwargs capture_device
        alias = kwargs.get("alias", "default")
        capture_device = kwargs.pop("capture_device")
        self.capture_factory = ToolFactory(capture_device=capture_device)
        logger.debug("Getting tool object...")
        logger.info("self.capture_factory",self.capture_factory)
        capture_obj = self.capture_factory.get_tool_obj()
        logger.info("capture_obj",capture_obj)
        capture_obj.traffic_capture_start(**kwargs)
        self.store.add(capture_obj, alias)

    @check_rat
    def traffic_capture_stop(self, **kwargs):
        """Stop traffic capture"""
        alias = kwargs.get("alias", "default")
        keep_alias = kwargs.get("keep_alias", False)
        capture_obj = self.store.get(alias)
        destination = capture_obj.traffic_capture_stop(**kwargs)
        logger.info("Capture file name: {}".format(destination))
        if not keep_alias:
            self.store.remove(alias)
        return destination

    def traffic_capture_abort(self, **kwargs):
        """Abort traffic capture"""
        alias = kwargs.get("alias", "default")
        capture_obj = self.store.get(alias)
        capture_obj.traffic_capture_abort(**kwargs)
        self.store.remove(alias)

    def upload_traffic_capture_file(self, **kwargs):
        """upload traffic capture file"""
        global_vars.traffic_capture_instance = False
        alias = kwargs.get("alias", "default")
        capture_obj = self.store.get(alias)
        info = capture_obj.upload_traffic_capture_file(**kwargs)
        logger.info("Absolute file path: {}".format(info))
        # self.store.remove(alias)
        return info

    def generate_capture_files(self, **kwargs):
        """generate ip traffic capture"""
        alias = kwargs.get("alias", "default")
        capture_obj = self.store.get(alias)
        info = capture_obj.generate_capture_files(**kwargs)
        logger.info("Generate info: {}".format(info))
        global_vars.traffic_capture_instance = False
        # self.store.remove(alias)
        return info